"""Shared visual tokens and controls for both themes."""

def stylesheet(alpha=255):
    return 'QFrame#root { background:rgba(255,255,255,%d);border:1px solid #d9e2de;border-radius:12px; }\n        QDialog {background:#ffffff;} QDialog#settingsDialog {background:transparent;} QWidget {font-family:"Microsoft YaHei UI";font-size:13px;color:#243a32;} QLabel {background:transparent;border:none;} QLabel#title {font-size:14px;font-weight:600;}\n        QLabel#banner {background:#eef4f0;border-radius:6px;padding:5px;color:#42594e;}\n        QPushButton {background:#edf3ef;border:1px solid #d7e3dc;border-radius:6px;padding:4px 6px;} QPushButton:hover {background:#dbece2;} QPushButton:disabled {color:#84958c;}\n        QListWidget#navigation {background:transparent;border:none;outline:0;} QListWidget#navigation::item {border-radius:5px;color:#42594e;} QListWidget#navigation::item:selected {background:#dcece2;color:#245f48;font-weight:600;} QTabBar {background:rgba(255,255,255,240);} QTabBar::tab {color:#42594e;padding:9px 15px;background:rgba(255,255,255,240);border-bottom:2px solid #e8eeea;} QTabBar::tab:selected {color:#276c52;border-bottom:2px solid #397461;font-weight:600;}\n        QScrollArea,QScrollArea>QWidget>QWidget {background:transparent;} QFrame#card {background:rgba(255,255,255,242);border:1px solid #e2e9e4;border-radius:8px;}\n        QComboBox,QSpinBox,QLineEdit {background:white;border:1px solid #cedbd3;border-radius:4px;padding:5px;} QCheckBox {background:transparent;} QScrollBar:vertical {width:8px;background:#f0f3f1;} QScrollBar::handle:vertical {background:#c1cec5;min-height:24px;}\n        QLabel#sectionTitle {font-size:14px;font-weight:600;color:#243a32;}\n        QLabel#settingsTitle {font-size:20px;font-weight:600;color:#243a32;}\n        QLabel#hint {color:#76857d;font-size:12px;}\n        QFrame#settingsCard {background:rgba(255,255,255,242);border:1px solid #e0e8e2;border-radius:10px;}\n        QPushButton#primary {background:#397461;color:white;border:1px solid #397461;padding:7px 15px;}\n        QPushButton#primary:hover {background:#2f654f;}\n        QPushButton#danger {background:#fff7f5;color:#ae5147;border:1px solid #f0dcd7;padding:7px 12px;}\n        QPushButton#themeChoice {padding:12px 18px;border:1px solid #dfe7e1;background:#f7faf8;}\n        QPushButton#themeChoice:checked {background:#e3f0e8;color:#27634a;border:1px solid #77a78b;}\n        QTabWidget#settingsTabs::pane {border:0;background:transparent;}\n        QTabBar::tab {border:0;border-radius:6px;padding:7px 20px;margin:3px;background:transparent;color:#74827a;}\n        QTabBar::tab:selected {background:#dcece2;color:#27634a;}\n        QCheckBox::indicator {width:30px;height:16px;border:1px solid #cdd9d1;border-radius:8px;background:#e5ebe7;}\n        QCheckBox::indicator:checked {background:#397461;border-color:#397461;}\n        QSlider::groove:horizontal {height:5px;background:#e4ebe6;border-radius:2px;}\n        QSlider::sub-page:horizontal {background:#6e9a80;border-radius:2px;}\n        QSlider::handle:horizontal {background:white;border:2px solid #397461;width:13px;height:13px;border-radius:7px;margin:-6px 0;}\n        QMenu {background:#ffffff;border:1px solid #dbe5df;border-radius:7px;padding:5px;}\n        QMenu::item {padding:7px 16px;}\n        QMenu::item:selected {background:#e3f0e8;color:#27634a;}\n' % alpha + 'QToolButton#toolIcon {background:#f3f8f5;border:1px solid #dce8e0;border-radius:14px;padding:10px;} QToolButton#toolIcon:hover {background:#e3f0e8;border-color:#82aa94;} QToolButton#toolIcon:pressed {background:#d5e8dc;} QToolButton#toolIcon:focus {border:2px solid #397461;}' 
